css:
.loader {
  width: 240px;
  height: 240px;
  position: relative;
  transition: 3s;

  .min-circle {
    width: calc(50% - 20px);
    height: 2px;
    border-radius: 50%;
    position: absolute;
    top: 50%;
    left: 0%;
    transform: rotate(calc(360deg / 120 * var(--p)));
    transform-origin: calc(100% + 20px) 50%;
    transition: 3s;
    animation: animar 1s steps(1) infinite;
    animation-delay: calc(-6050ms + var(--p) * 50ms);
    background: dodgerblue;

    &:nth-child(odd) {
      background: springgreen;
    }
  }

  &:hover {
    width: 360px;
    height: 360px;
  }
}

@keyframes animar {
  50% {
    background: #0000;
  }
}
